    private Topology parseTopology(Path file,int nonce,int expectedTopology)throws Exception{byte[]b=Files.readAllBytes(file);try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(b))){require(b.length==44&&in.readInt()==0x574c3834&&in.readInt()==1&&in.readInt()==44&&in.readInt()==nonce,"topology schema drift");int x=in.readInt(),y=in.readInt(),z=in.readInt(),request=in.readInt(),event=in.readInt(),topology=in.readInt(),rebuilds=in.readInt();require(in.read()==-1&&request>=300&&event>=request&&topology==expectedTopology&&rebuilds==topology,"topology event drift");return new Topology(x,y,z,request,event,topology,rebuilds);}}
    private Census parseCensus(Path file,Topology change,int nonce)throws Exception{byte[]bytes=Files.readAllBytes(file);try(DataInputStream in=new DataInputStream(new ByteArrayInputStream(bytes))){require(in.readInt()==0x574c3734&&in.readInt()==1&&in.readInt()==28&&in.readInt()==16&&in.readInt()==nonce,"census schema drift");int x=in.readInt(),y=in.readInt(),z=in.readInt();require(in.readInt()==720&&in.readLong()==12_000_000_000L,"census window drift");int count=in.readInt();long elapsed=in.readLong();require(x==change.x&&y==change.y&&z==change.z&&change.event<count&&count>=720&&count<=65536&&bytes.length==56L+count*28L,"census length/identity drift");long sum=0;long[]frames=new long[count];for(int i=0;i<count;i++){long delta=in.readLong();int renders=in.readInt(),lists=in.readInt(),visible=in.readInt(),calls=in.readInt(),state=in.readUnsignedShort(),mask=in.readUnsignedShort();require(delta>0&&renders==1&&lists==1&&visible>0&&calls==(i<change.event?16:13)&&state==0x1010&&mask==0xffff,"topology census record drift at "+i+" values="+renders+"/"+lists+"/"+calls);frames[i]=delta;sum=Math.addExact(sum,delta);}require(in.read()==-1&&sum==elapsed&&elapsed>=12_000_000_000L,"census aggregate drift");return new Census(x,y,z,count,elapsed,frames);}}
