    private List<String>command(Path tree,Path init,String role,Path game,int port,int nonce,int topology,Path census,Path paged,Path artifact,Plan plan){String wrapper=System.getProperty("os.name").startsWith("Windows")?"gradlew.bat":"gradlew";List<String>r=new ArrayList<>(Arrays.asList(tree.resolve("stationapi/test-bare").resolve(wrapper).toString(),"--no-daemon","--init-script",init.toString(),role.equals("server")?"runServer":"runClient","-PworldlineRole="+role,"-PworldlineRunDir="+game,"-PworldlinePort="+port,"-PworldlineNonce="+nonce,"-PworldlineTopology="+topology));if(plan!=null)r.addAll(Arrays.asList("-PworldlinePlanX="+plan.x,"-PworldlinePlanY="+plan.y,"-PworldlinePlanZ="+plan.z));if(census!=null)r.addAll(Arrays.asList("-PworldlineArtifact="+census,"-PworldlinePagedArtifact="+paged,"-PworldlineTopologyArtifact="+artifact,"-PworldlineChangeAfter="+value("change.after.records"),"-PworldlineRebuildsPerFrame="+value("aero.rebuilds.per.frame"),"-PworldlineUsername="+value("username"),"-PworldlineWarmupFrames="+value("warmup.frames"),"-PworldlineWarmupMillis="+value("warmup.millis"),"-PworldlineMinimumFrames="+value("minimum.frames"),"-PworldlineMinimumMillis="+value("minimum.millis"),"-PworldlineFpsLimit="+value("fps.limit"),"-PworldlineAeroFramePacing="+value("aero.frame.pacing")));return r;}
