    private Captured startServer(Path d,List<String>c,int t)throws Exception{Captured s=Captured.start(d,c);try{s.awaitText("Done (",Math.addExact(timeout(t),60));return s;}catch(Exception e){s.kill();throw e;}}private String runGradle(Path d,List<String>c,int t)throws Exception{return Captured.run(d,c,timeout(t));}private int timeout(int t){String extra=System.getenv("WORLDLINE_RUNTIME_TIMEOUT_EXTRA");return extra==null?t:Math.addExact(t,Integer.parseInt(extra));}private void verifyBoundary()throws IOException{for(Path base:Arrays.asList(root.resolve("smokes/m74-complete-aero-census/runtime-src/worldline/m74"),smoke.resolve("runtime-src")))try(Stream<Path>p=Files.walk(base)){for(Path f:p.filter(x->x.toString().endsWith(".java")).filter(x->!x.toString().contains(File.separator+"client"+File.separator)).filter(x->!x.toString().contains(File.separator+"mixin"+File.separator)).collect(Collectors.toList())){String s=Files.readString(f);require(!s.contains("aero.modellib")&&!s.contains("net.minecraft.client")&&!s.contains("org.lwjgl"),"server closure imports client code");}}}
    private void verifyCheckout(Path c)throws Exception{require(git(c,"remote","get-url","origin").trim().equals(value("aero.repository"))&&git(c,"rev-parse","HEAD").trim().equals(value("aero.revision"))&&git(c,"status","--porcelain","--untracked-files=all").trim().isEmpty(),"Aero checkout drift");}private void addWorktree(Path c,Path t)throws Exception{Files.createDirectories(t.getParent());git(c,"worktree","add","--detach",t.toString(),value("aero.revision"));verifyWorktree(t);}private void verifyWorktree(Path t)throws Exception{require(git(t,"rev-parse","HEAD").trim().equals(value("aero.revision"))&&git(t,"status","--porcelain","--untracked-files=all").trim().isEmpty(),"worktree drift");}
